mapper.select:
SELECT a.*
FROM fcc_agent a
LEFT JOIN fcc_agent_presence p ON p.agent_id = a.id
WHERE a.deleted_at IS NULL

  AND a.agent_name LIKE CONCAT('%', #{agentName}, '%')


  AND a.phone_number LIKE CONCAT('%', #{phoneNumber}, '%')


  AND a.work_no = #{workNo}


  AND a.role_code = #{roleCode}


  AND a.status = #{status}


  AND a.updated_at >= #{startTime}


  AND a.updated_at <= #{endTime}


  AND p.login_status IN ('LOGIN', 'LOGIN_BUSY')


  AND (p.login_status IS NULL OR p.login_status = 'LOGOUT')

ORDER BY a.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM fcc_agent a
LEFT JOIN fcc_agent_presence p ON p.agent_id = a.id
WHERE a.deleted_at IS NULL

  AND a.agent_name LIKE CONCAT('%', #{agentName}, '%')


  AND a.phone_number LIKE CONCAT('%', #{phoneNumber}, '%')


  AND a.work_no = #{workNo}


  AND a.role_code = #{roleCode}


  AND a.status = #{status}


  AND a.updated_at >= #{startTime}


  AND a.updated_at <= #{endTime}


  AND p.login_status IN ('LOGIN', 'LOGIN_BUSY')


  AND (p.login_status IS NULL OR p.login_status = 'LOGOUT')
